=== FILE: tb_crc8_block.v ===
`timescale 1ns / 1ps
// Self-checking constrained-random testbench for crc8_block.
// Reference: interface_spec.md (approved), requirements CRC-RESET, CRC-INIT,
// CRC-POLY, CRC-ORDER, CRC-HOLD, CRC-FINAL, CRC-EMPTY.
// The model below is written from the specification text, not from the RTL.
// Inputs are driven on the falling edge; outputs are compared 1 ns after each
// rising edge, and also after each input change with no edge in between.
module tb_crc8_block;
    // ---------------- knobs ----------------
    localparam integer N_RANDOM = 20000;  // random cycles
    localparam integer P_RESET  = 2;      // percent of cycles with rst_n low
    localparam integer P_INIT   = 6;      // percent of cycles with init high
    localparam integer P_VALID  = 75;     // percent of cycles with valid high

    // ---------------- DUT ----------------
    reg        clk   = 1'b0;
    reg        rst_n = 1'b0;
    reg        init  = 1'b0;
    reg        valid = 1'b0;
    reg  [7:0] data  = 8'h00;
    wire [7:0] crc;

    crc8_block dut (
        .clk  (clk),
        .rst_n(rst_n),
        .init (init),
        .valid(valid),
        .data (data),
        .crc  (crc)
    );

    always #5 clk = ~clk;

    // ---------------- bookkeeping ----------------
    integer n_pass;
    integer n_fail;
    integer seed;
    integer cycle;
    reg [7:0] model;
    reg       model_known;
    reg [8*64-1:0] nonce;

    integer cov_reset, cov_reset_valid, cov_reset_init, cov_reset_mid;
    integer cov_init, cov_init_valid, cov_init_mid;
    integer cov_bytes, cov_hold, cov_d00, cov_dff, cov_onehot;
    integer frame_len, max_frame;

    // ---------------- reference model (from spec 2.2) ----------------
    // MSB-first, unreflected CRC with polynomial 0x07: XOR the whole byte into
    // the running value, then eight times shift left and, if the bit shifted
    // out was 1, XOR with 0x07. Equivalent to the spec's bit-by-bit wording.
    function [7:0] spec_take_byte(input [7:0] run, input [7:0] b);
        reg [8:0] acc;
        integer k;
        begin
            acc = {1'b0, run ^ b};
            for (k = 0; k < 8; k = k + 1) begin
                acc = {acc[7:0], 1'b0};          // acc[8] = bit shifted out
                if (acc[8])
                    acc[7:0] = acc[7:0] ^ 8'h07;
            end
            spec_take_byte = acc[7:0];
        end
    endfunction

    // Spec 2.1 / 2.2: reset loads 0xFF; init loads 0xFF and wins over valid;
    // valid takes a byte; otherwise hold.
    function [7:0] spec_next(input [7:0] run, input r_n, input i_init,
                             input i_valid, input [7:0] b);
        begin
            if (!r_n)
                spec_next = 8'hFF;
            else if (i_init)
                spec_next = 8'hFF;
            else if (i_valid)
                spec_next = spec_take_byte(run, b);
            else
                spec_next = run;
        end
    endfunction

    // ---------------- checking ----------------
    task check(input [7:0] expected, input [8*24-1:0] tag);
        begin
            if (crc === expected) begin
                n_pass = n_pass + 1;
            end else begin
                n_fail = n_fail + 1;
                if (n_fail <= 20)
                    $display("MISMATCH %0s cycle=%0d rst_n=%b init=%b valid=%b data=%h crc=%h expected=%h",
                             tag, cycle, rst_n, init, valid, data, crc, expected);
            end
        end
    endtask

    task cover_goal(input integer count, input integer minimum, input [8*24-1:0] name);
        begin
            $display("COVER %0s = %0d (goal >= %0d)", name, count, minimum);
            if (count >= minimum) begin
                n_pass = n_pass + 1;
            end else begin
                n_fail = n_fail + 1;
                $display("COVER-HOLE %0s reached %0d, goal %0d", name, count, minimum);
            end
        end
    endtask

    // One clock cycle: drive at negedge, check no-edge stability, update the
    // model at posedge, check after the edge.
    task step(input r_n, input i_init, input i_valid, input [7:0] i_data);
        reg [7:0] prev;
        begin
            @(negedge clk);
            rst_n = r_n;
            init  = i_init;
            valid = i_valid;
            data  = i_data;
            #1;
            if (model_known)
                check(model ^ 8'hFF, "no-edge");     // CRC-FINAL: no change without an edge
            @(posedge clk);
            prev = model;
            if (!r_n) begin
                cov_reset = cov_reset + 1;
                if (i_valid) cov_reset_valid = cov_reset_valid + 1;
                if (i_init)  cov_reset_init  = cov_reset_init + 1;
                if (model_known && prev != 8'hFF) cov_reset_mid = cov_reset_mid + 1;
                frame_len = 0;
            end else if (i_init) begin
                cov_init = cov_init + 1;
                if (i_valid) cov_init_valid = cov_init_valid + 1;
                if (model_known && prev != 8'hFF) cov_init_mid = cov_init_mid + 1;
                frame_len = 0;
            end else if (i_valid) begin
                cov_bytes = cov_bytes + 1;
                frame_len = frame_len + 1;
                if (frame_len > max_frame) max_frame = frame_len;
                if (i_data == 8'h00) cov_d00 = cov_d00 + 1;
                if (i_data == 8'hFF) cov_dff = cov_dff + 1;
                if ((i_data != 8'h00) && ((i_data & (i_data - 8'd1)) == 8'h00))
                    cov_onehot = cov_onehot + 1;
            end else begin
                cov_hold = cov_hold + 1;
            end
            model = spec_next(prev, r_n, i_init, i_valid, i_data);
            if (!r_n || i_init)
                model_known = 1'b1;
            cycle = cycle + 1;
            #1;
            if (model_known)
                check(model ^ 8'hFF, "after-edge");
        end
    endtask

    // ---------------- stimulus ----------------
    integer k;
    integer pick;
    reg     r_rst_n, r_init, r_valid;
    reg [7:0] r_data;

    initial begin
        n_pass = 0;
        n_fail = 0;
        cycle  = 0;
        model  = 8'hxx;
        model_known = 1'b0;
        cov_reset = 0; cov_reset_valid = 0; cov_reset_init = 0; cov_reset_mid = 0;
        cov_init = 0; cov_init_valid = 0; cov_init_mid = 0;
        cov_bytes = 0; cov_hold = 0; cov_d00 = 0; cov_dff = 0; cov_onehot = 0;
        frame_len = 0; max_frame = 0;

        nonce = "NONCE-NOT-GIVEN";
        if (!$value$plusargs("nonce=%s", nonce))
            if (!$value$plusargs("NIRMAAN_NONCE=%s", nonce))
                if (!$value$plusargs("nirmaan_nonce=%s", nonce))
                    nonce = "NONCE-NOT-GIVEN";

        seed = 32'h1F2E3D4C;
        if ($value$plusargs("seed=%d", seed))
            $display("SEED override from plusarg");
        $display("SEED %0d", seed);

        // ---------- directed phase: literal expectations computed by hand ----------
        step(1'b0, 1'b0, 1'b0, 8'h00);
        step(1'b0, 1'b0, 1'b0, 8'h00);
        check(8'h00, "D1 reset empty");           // CRC-RESET, CRC-EMPTY
        step(1'b0, 1'b0, 1'b1, 8'hA5);
        check(8'h00, "D2 reset beats valid");     // CRC-RESET
        step(1'b1, 1'b0, 1'b1, 8'hFF);
        check(8'hFF, "D3 byte FF");               // CRC-POLY
        step(1'b1, 1'b1, 1'b1, 8'h5A);
        check(8'h00, "D4 init beats valid");      // CRC-INIT
        step(1'b1, 1'b0, 1'b1, 8'h00);
        check(8'h0C, "D5 byte 00");               // CRC-POLY
        step(1'b1, 1'b0, 1'b0, 8'h33);
        check(8'h0C, "D6 hold");                  // CRC-HOLD
        step(1'b1, 1'b0, 1'b1, 8'h00);
        check(8'h28, "D7 bytes 00 00");           // CRC-POLY, two bytes
        step(1'b1, 1'b1, 1'b0, 8'h00);
        check(8'h00, "D8 reload empty");          // CRC-INIT, CRC-EMPTY
        step(1'b1, 1'b0, 1'b1, 8'h80);
        check(8'h85, "D9 byte 80");               // CRC-ORDER
        step(1'b1, 1'b1, 1'b0, 8'h00);
        step(1'b1, 1'b0, 1'b1, 8'h01);
        check(8'h0B, "D10 byte 01");              // CRC-ORDER
        step(1'b0, 1'b1, 1'b1, 8'h77);
        check(8'h00, "D11 reset mid-frame");      // CRC-RESET

        // ---------- constrained-random phase ----------
        for (k = 0; k < N_RANDOM; k = k + 1) begin
            r_rst_n = (({$random(seed)} % 100) >= P_RESET);
            r_init  = (({$random(seed)} % 100) <  P_INIT);
            r_valid = (({$random(seed)} % 100) <  P_VALID);
            pick    = {$random(seed)} % 100;
            if (pick < 15)
                r_data = 8'h00;
            else if (pick < 30)
                r_data = 8'hFF;
            else if (pick < 45)
                r_data = 8'h01 << ({$random(seed)} % 8);
            else
                r_data = $random(seed);
            step(r_rst_n, r_init, r_valid, r_data);
        end

        // ---------- coverage goals: fail the run if a corner was not reached ----------
        cover_goal(cov_reset_valid, 10,   "reset_with_valid");
        cover_goal(cov_reset_init,  3,    "reset_with_init");
        cover_goal(cov_reset_mid,   10,   "reset_mid_frame");
        cover_goal(cov_init_valid,  20,   "init_with_valid");
        cover_goal(cov_init_mid,    20,   "init_mid_frame");
        cover_goal(cov_hold,        500,  "hold_cycles");
        cover_goal(cov_bytes,       5000, "bytes_taken");
        cover_goal(cov_d00,         200,  "data_00");
        cover_goal(cov_dff,         200,  "data_FF");
        cover_goal(cov_onehot,      200,  "data_onehot");
        cover_goal(max_frame,       16,   "longest_frame");

        $display("SUMMARY seed=%0d cycles=%0d", seed, cycle);
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, n_pass, n_fail);
        $finish;
    end
endmodule
=== END FILE ===
